head.script:
// [ISSUE 재현 샘플]
// wframe.setReadOnly(true) 호출 시 wframe 자체에는 readonly 속성이 적용되지만,
// 내부에 로드된 WebSquare XML 페이지의 자식 input 컴포넌트에는 readonly 가 전파되지 않음.
//
// 재현 절차:
//   1. "setReadOnly(true)" 버튼 클릭
//   2. "DOM 상태 확인" 버튼 클릭
//
// 기대 결과:
//   - wframe (target1)                : readonly = "readonly"
//   - 자식 input (target1_child_input) : readonly = "readonly"
//
// 실제 결과 (이슈):
//   - wframe (target1)                : readonly = "readonly"       (정상)
//   - 자식 input (target1_child_input) : readonly 속성 없음, el.readOnly=false  ← 미전파

scwin.onpageload = function () {};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

scwin.btn_setReadOnlyTrue_onclick = function () {
    target1.setReadOnly(true);
    scwin.setReturnValue("target1.setReadOnly(true) 호출 완료");
};

scwin.btn_setReadOnlyFalse_onclick = function () {
    target1.setReadOnly(false);
    scwin.setReturnValue("target1.setReadOnly(false) 호출 완료");
};

scwin.btn_check_onclick = function () {
    const targets = [
        { label: 'wframe       (target1)',              sel: '#mf_target1'                          },
        { label: 'input        (target1_child_input)',     sel: '#mf_target1_child_input'              },
        { label: 'textarea     (target1_child_textarea)',  sel: '#mf_target1_child_textarea'           },
        { label: 'selectbox    (target1_child_selectbox)', sel: '#mf_target1_child_selectbox'          },
        { label: 'inputCalendar(target1_child_calendar)',  sel: '#mf_target1_child_calendar_input'     }
    ];

    scwin.setReturnValue("=== DOM readonly 상태 ===");
    targets.forEach(t => {
        const el = document.querySelector(t.sel);
        if (el) {
            scwin.setReturnValue(t.label + ' : readonly=' + el.getAttribute('readonly') + ', el.readOnly=' + el.readOnly);
        } else {
            scwin.setReturnValue(t.label + ' : DOM 미존재');
        }
    });
};
